// M=104 (100 bases padded to next multiple of T=8)
// E=5  T=8  Y=4  CHAR_W=3
// DNA encoding: A=000 C=001 G=010 T=011 B=100(pad)
// ============================================================
`timescale 1ns/1ps

module snake_100pairs_tb;

    localparam E        = 5;
    localparam T        = 8;
    localparam Y        = 4;
    localparam M        = 104;
    localparam CHAR_W   = 3;
    localparam SEQ_LEN  = 100;
    localparam Q_TOT    = M + 2*E;
    localparam CLK_HALF = 5;
    localparam NUM_PAIRS = 99;

    localparam [CHAR_W-1:0] BA = 3'b000;
    localparam [CHAR_W-1:0] BC = 3'b001;
    localparam [CHAR_W-1:0] BG = 3'b010;
    localparam [CHAR_W-1:0] BT = 3'b011;
    localparam [CHAR_W-1:0] BB = 3'b100;

    reg                     clk, rst, start_i;
    wire                    done_o, accept_o;
    reg  [M*CHAR_W-1:0]     ref_i;
    reg  [Q_TOT*CHAR_W-1:0] query_i;

    snake_on_chip_top #(.E(E),.T(T),.Y(Y),.M(M),.CHAR_W(CHAR_W)) DUT (
        .clk(clk),.rst(rst),.start_i(start_i),
        .done_o(done_o),.accept_o(accept_o),
        .ref_i(ref_i),.query_i(query_i)
    );

    initial clk = 0;
    always #CLK_HALF clk = ~clk;

    integer timeout_c;
    integer total_accepted, total_rejected;

    // Arrays to store per-pair results for final summary table
    integer pair_obs    [1:NUM_PAIRS];
    integer pair_accept [1:NUM_PAIRS];

    task reset_dut;
        begin
            rst=1; start_i=0;
            repeat(4) @(posedge clk);
            rst=0; @(posedge clk); #1;
        end
    endtask

    task run_pair;
        input integer tid;
        begin
            @(posedge clk); #1;
            start_i=1; @(posedge clk); #1; start_i=0;
            timeout_c=0;
            while (!done_o && timeout_c<2000) begin
                @(posedge clk); #1; timeout_c=timeout_c+1;
            end
            if (!done_o) begin
                //$display("  Pair %3d: TIMEOUT", tid);
                pair_obs[tid]    = -1;
                pair_accept[tid] = -1;
            end else begin
                // Read total_obs directly from DUT internal register
                pair_obs[tid]    = DUT.total_obs;
                pair_accept[tid] = accept_o;
                if (accept_o) begin
                    total_accepted = total_accepted + 1;
                end else begin
                    total_rejected = total_rejected + 1;
                end
            end
            repeat(5) @(posedge clk); #1;
        end
    endtask

    integer p;

    initial begin
        total_accepted=0; total_rejected=0;
        clk=0; rst=1; start_i=0; ref_i=0; query_i=0;

        $display("============================================================");
        $display("  Snake-on-Chip  100-Pair Dataset TB");
        $display("  E=%0d T=%0d Y=%0d M=%0d SEQ_LEN=%0d",E,T,Y,M,100);
        $display("  ACCEPT if total_obstacles <= E=%0d",E);
        $display("============================================================");

        repeat(4) @(posedge clk); rst=0; @(posedge clk); #1;

